test_a_signal_block_starts_in_one_year:
for member in block[1:]:
    for t in shared:
        model.add_linear_constraint(x[member, t] == x[lead, t], name=f"block_{member}_{t}")

test_one_track_upgrade_is_enough:
for k in tracks:
    track_by = sum(x[k, u] for u in starts[k] if u <= t - 1)
    model.add_linear_constraint(platform_by <= track_by, name=f"carried_{platform}_{k}_{t}")
